// Demo entry point (`wrangler dev --env demo` / `npm run dev:demo`).
//
// Same app as production, but occupancy is generated by the mock source and an
// empty database is seeded with a few days of history, so the map and the
// busyness graph work with no live data. Uses its own D1 database, so demo
// data can never end up in the real app's history.

import { createApp } from '../app.js';
import { fetchOccupancy } from './mockSource.js';
import { seedHistoryIfNeeded } from './seed.js';

function intFrom(raw, fallback) {
  const n = Number.parseInt(raw, 10);
  return Number.isFinite(n) && n > 0 ? n : fallback;
}

export const demoSource = {
  name: 'demo',
  fetchOccupancy: () => fetchOccupancy(),

  // Before each poll: top up demo history if the database is (nearly) empty.
  async prepare(env) {
    const r = await seedHistoryIfNeeded(env.DB, { days: intFrom(env.SEED_DAYS, 1) });
    if (r.seeded) console.log(`[seed] wrote ${r.snapshots} demo snapshots (${r.reason})`);
  },

  // A page view on an empty demo database seeds + polls straight away.
  pollWhenEmpty: true,
};

export default createApp(demoSource);
